/// <summary>
/// Runs all environment data setup tests from the web client and shows the results in the infolog.
/// </summary>
/// <remarks>
/// Open it with ?mi=SysClassRunner&cls=OLK_EnvironmentDataSetupTestJob. Each test method runs after its own setUp and before its
/// own tearDown, so the run does not depend on the Visual Studio test runner. The tests can also be run from the Test Explorer.
/// </remarks>
internal final class OLK_EnvironmentDataSetupTestJob
{
}

Method.Source:
private static container testClasses()
{
    return [
        classNum(OLK_EnvironmentDataSetupTest),
        classNum(OLK_EnvironmentDataSetupSqlTest),
        classNum(OLK_EnvironmentDataSetupCodeJobTest),
        classNum(OLK_EnvironmentDataSetupDefaultValuesTest),
        classNum(OLK_EnvironmentDataSetupPersonalizationTest),
        classNum(OLK_EnvironmentDataSetupLogTest)];
}

public static void main(Args _args)
{
    container   classes = OLK_EnvironmentDataSetupTestJob::testClasses();
    int         passed;
    int         failed;

    for (int i = 1; i <= conLen(classes); i++)
    {
        ClassId         classId   = conPeek(classes, i);
        SetEnumerator   tests     = OLK_EnvironmentDataSetupTestJob::testMethods(classId).getEnumerator();

        while (tests.moveNext())
        {
            if (OLK_EnvironmentDataSetupTestJob::runTest(classId, tests.current()))
            {
                passed++;
            }
            else
            {
                failed++;
            }
        }
    }

    if (failed)
    {
        error(strFmt('Environment data setup tests: %1 passed, %2 failed.', passed, failed));
    }
    else
    {
        info(strFmt('Environment data setup tests: %1 passed, %2 failed.', passed, failed));
    }
}

/// <summary>
/// The test methods of a test class, in name order.
/// </summary>
private static Set testMethods(ClassId _classId)
{
    SetEnumerator   methods   = new SysDictClass(_classId).methods(true, false, false).getEnumerator();
    Set             testNames = new Set(Types::String);

    while (methods.moveNext())
    {
        DictMethod dictMethod = methods.current();

        if (dictMethod.getAttribute(classStr(SysTestMethodAttribute)))
        {
            testNames.add(dictMethod.name());
        }
    }

    return testNames;
}

private static boolean runTest(ClassId _classId, MethodName _testName)
{
    SysDictClass    dictClass    = new SysDictClass(_classId);
    SysTestCase     test         = dictClass.makeObject();
    str             testName     = strFmt('%1.%2', classId2Name(_classId), _testName);
    int             infologStart = infologLine();
    str             failure;

    try
    {
        test.setUp();
        dictClass.callObject(_testName, test);
    }
    catch (Exception::CLRError)
    {
        failure = CLRInterop::getLastException().ToString();
    }
    catch
    {
        failure = infologLine() > infologStart ? infolog.text(infologLine()) : 'Unknown error';
    }

    try
    {
        test.tearDown();
    }
    catch
    {
        if (!failure)
        {
            failure = infologLine() > infologStart ? infolog.text(infologLine()) : 'tearDown failed';
        }
    }

    if (failure)
    {
        error(strFmt('FAILED %1: %2', testName, failure));
        return false;
    }

    info(strFmt('Passed %1', testName));
    return true;
}
